with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('komme til', 'phrase', 'dfb4aa8a-ba86-5532-bcb3-907d41c58978', 1, 'verb', null, 'приходити, прибувати (кудись)', 'Jeg kom til stationen for sent i morges.', 'Я прийшов на станцію занадто пізно сьогодні вранці.'), ('sige til', 'phrase', '24dc0ab0-4034-5387-86f4-39dd96a992fe', 1, 'verb', null, 'повідомляти (давати знати)', 'Jeg siger til, hvis jeg kommer for sent.', 'Я дам знати, якщо запізнюся.'), ('lade være', 'phrase', '0d4d7509-0343-5f91-86e1-3b49896ac61f', 1, 'verb', null, 'переставати (робити щось)', 'Han lovede at lade være med at ryge.', 'Він пообіцяв не курити.'), ('tage til', 'phrase', '24aef06b-0b0c-52c8-9e17-d31a45e03fbc', 1, 'verb', null, 'вирушати до (місця)', 'Vi tager til stranden i morgen.', 'Завтра ми їдемо на пляж.'), ('tage til', 'phrase', '97b8b72f-33cd-5c1c-86da-752f4ee85041', 2, 'verb', null, 'набирати (вагу, швидкість)', 'Bilen tager til i fart på motorvejen.', 'Автомобіль збільшує швидкість на шосе.'), ('gå med', 'phrase', 'a5f09b10-a08b-5a34-b8d1-534b557a44ff', 1, 'verb', null, 'піти разом, приєднатися', 'Vil du gå med til festen på lørdag?', 'Хочеш піти з нами на вечірку в суботу?'), ('gå med', 'phrase', '7a91d63c-71af-58e5-9b0a-516e04ae8aa4', 2, 'verb', null, 'носити (одяг, аксесуари)', 'Hun gik med en rød kjole i går.', 'Вчора вона носила червону сукню.'), ('gå på', 'phrase', 'bc3d15dd-b6cb-55ee-a4ba-8608712aa11b', 1, 'verb', null, 'відвідувати (школу, курси)', 'Hun gik på universitetet i tre år.', 'Вона ходила до університету три роки.'), ('gå ind', 'phrase', '7c4faba9-da97-572d-a6c9-7e09fa804690', 1, 'verb', null, 'заходити', 'Hun gik ind i huset uden at banke på.', 'Вона зайшла в будинок, не постукавши.'), ('give sig', 'phrase', '3b626196-43ed-5cdd-9f96-ed648e6b8723', 1, 'verb', null, 'вщухати (про біль, погоду)', 'Regnen gav sig endelig sidst på dagen.', 'Дощ нарешті вщух наприкінці дня.'), ('give sig', 'phrase', '34ed29d2-fc13-59b2-bdfe-57512e33beba', 2, 'verb', null, 'здаватися, поступатися', 'Han gav sig til sidst og sagde ja.', 'Він нарешті здався і погодився.'), ('være nødt til', 'phrase', 'e3047c10-bf32-5c7e-8551-daa908847e4d', 1, 'verb', null, 'бути змушеним (щось зробити)', 'Jeg er nødt til at gå nu.', 'Мені треба йти.'), ('tænke sig', 'phrase', 'e4743403-91fc-5535-9b7e-064e11d61277', 1, 'verb', null, 'уявляти собі', 'Tænk dig en verden uden biler.', 'Уяви світ без автомобілів.'), ('sidde på', 'phrase', '2def98ef-3b3d-5794-a61a-2b3b0a9ff441', 1, 'verb', null, 'сидіти на (чомусь)', 'Katten sidder på stolen hele dagen.', 'Кіт сидить на стільці цілий день.'), ('sidde på', 'phrase', '82120d26-ba58-5c66-8022-a933ef320713', 2, 'verb', null, 'утримувати (інформацію, секрет)', 'Hun sad på hemmeligheden i mange år.', 'Вона зберігала цю таємницю багато років.'), ('tænke sig at', 'phrase', '75ea44ac-4248-5807-8442-e8586ea47108', 1, 'verb', null, 'уявляти собі (що)', 'Tænk dig at bo i sådan et hus.', 'Уяви собі життя в такому будинку.'), ('spille på', 'phrase', '2138f8fb-1739-557f-a1cd-d66fccfbb900', 1, 'verb', null, 'грати на (музичному інструменті)', 'Han spiller på guitar hver aften.', 'Він грає на гітарі щовечора.'), ('skrive til', 'phrase', 'd92c6556-bf4d-5bbb-a471-f91871b1cb3c', 1, 'verb', null, 'писати (комусь)', 'Jeg skriver til min ven hver uge.', 'Я пишу своєму другові щотижня.'), ('stå på', 'phrase', 'd71e450f-8bd8-5d44-9f61-e8f1069b50b1', 1, 'verb', null, 'тривати', 'Mødet står på i to timer.', 'Зустріч триває дві години.'), ('have lyst', 'phrase', '090dfece-973c-5b61-9024-61ab437756f9', 1, 'verb', null, 'хотіти (мати бажання)', 'Jeg har lyst til en kop te.', 'Мені хочеться чашки чаю.'), ('gå ned', 'phrase', '6f7cc22d-c22f-54a3-be77-2aeaf58fbc2d', 1, 'verb', null, 'спускатися (вниз)', 'Vi gik ned ad trappen til stuen.', 'Ми спустилися сходами до вітальні.'), ('gå ned', 'phrase', 'fed3e2ef-d7ec-5feb-b4fd-8ceb7644c6b8', 2, 'verb', null, 'сідати (про сонце)', 'Solen går ned klokken otte om aftenen.', 'Сонце заходить о восьмій вечора.'), ('gå ned', 'phrase', 'ad72cdba-2806-5866-805f-4ab1d80628c7', 3, 'verb', null, 'зменшуватися (про ціну, вагу)', 'Prisen på mælk er gået ned i denne uge.', 'Ціна на молоко цього тижня знизилася.'), ('slå sig', 'phrase', '0320fc18-c821-52d6-a8bb-67680210a0a5', 1, 'verb', null, 'вдаритися, поранитися', 'Jeg slog mig på knæet, da jeg faldt.', 'Я забив коліно, коли впав.'), ('rejse til', 'phrase', '562dd029-48c3-5d1e-b998-36881b2a0de1', 1, 'verb', null, 'їхати, подорожувати (кудись)', 'Vi rejser til Spanien hver sommer.', 'Щоліта ми їздимо до Іспанії.'), ('være til', 'phrase', '097ffea8-5b2c-5157-ae75-4c85e3f3e09f', 1, 'verb', null, 'існувати', 'Mange tror, at spøgelser er til.', 'Багато людей вірять, що привиди існують.'), ('blive til', 'phrase', 'fb8e0fea-8f18-5979-b681-929fd04e10e5', 1, 'verb', null, 'ставати (перетворюватися)', 'Vandet blev til is i løbet af natten.', 'Вода вночі перетворилася на лід.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0001' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
